describe('Login Loading Spinner', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display loading spinner while login request is processing', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in login form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for the API call to be made
    cy.wait('@loginRequest');

    // Verify loading spinner is visible
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Verify login button is disabled during loading
    cy.get('[data-testid="login-button"]').should('be.disabled');

    // Verify spinner has a specific class or attribute
    cy.get('[data-testid="loading-spinner"]').should('have.class', 'is-loading');

    // Verify spinner is removed after successful login
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');
  });

  it('should hide loading spinner when login request fails', () => {
    // Intercept login API call and return an error response
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('loginRequest');

    // Fill in login form with invalid credentials
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for the failed API call
    cy.wait('@loginRequest');

    // Verify loading spinner is visible during request
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Verify loading spinner is hidden after error
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify login button is re-enabled
    cy.get('[data-testid="login-button"]').should('not.be.disabled');

    // Verify user remains on login page
    cy.url().should('include', '/login');
  });
});
